import{_ as e,o as l,c as a,a4 as i}from"./chunks/framework.2-Vke5-n.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"Webフロントエンド<wbr>設計ガイドライン","tagline":"Web Frontend Design Guidelines","actions":[{"theme":"brand","text":"Webフロントエンド設計ガイドライン","link":"./web_frontend_guidelines.md"}]}},"headers":[],"relativePath":"documents/forWebFrontend/index.md","filePath":"documents/forWebFrontend/index.md"}'),r={name:"documents/forWebFrontend/index.md"};function n(d,t,o,s,c,h){return l(),a("div",null,[...t[0]||(t[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>昨今のWebフロントエンド領域は、単なるHTML、CSS、JavaScriptでのページ制作から、React、Vue.jsなどのモダンなフレームワークを活用した大規模かつ動的なWebアプリケーションの構築へと変化している。これにより、開発の効率化とユーザー体験（UX）が向上する一方で、設計の考慮点も多様化している。また、セキュリティ、アクセシビリティなどより多面的な品質も求められている。本ガイドラインでは、Webフロントエンド設計における考慮点・設計パターン・推奨手法を提示し、開発チームが設計方針を決めるための土台を提供する。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>本ガイドラインは、Webフロントエンドの開発者・アーキテクトを対象とする。</p><p>以下の項目は解説しない。</p><ul><li>基本的なWeb技術に関する知識（HTML、CSS、JavaScript、HTTP通信など）</li><li>React、Vue.jsなどのフレームワークの基礎知識</li></ul><p>本ガイドラインの適用範囲は、ブラウザ上で動作するWebフロントエンドを対象とし、バックエンド（サーバーサイド）は対象外とする。また、一般的にフロントエンド領域に含まれることもある以下の領域も対象外とする。</p><ul><li>CDN（Contents Delivery Network）</li><li>BFF（Backend For Frontend）</li></ul><p>また、本ガイドラインは基本的に、<strong>業務アプリケーションの開発</strong> を想定して作成している。例えば大規模なtoC向けサービスと比較して、以下のような特性を持つことが多い点を考慮しているためである。</p><ul><li>権限管理が細かく、所属部署や役職で表示内容が細かく変わる、データの更新頻度が高いなどの理由で、CDN等を用いた積極的なキャッシュ戦略の効果が限定的</li><li>複雑なデータ入力フォームや、多機能なテーブル表示など、状態管理やUI制御が複雑になりやすい</li><li>利用するデバイスは比較的、絞り込みやすい</li></ul><p>なお、ホスティング方式など、インフラ構成に関する記述はAWSを前提とする。</p><h2 id="用語" tabindex="-1">用語 <a class="header-anchor" href="#用語" aria-label="Permalink to &quot;用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">toB</td><td style="text-align:left;">企業向けのサービスの意味</td></tr><tr><td style="text-align:left;">toC</td><td style="text-align:left;">一般消費者向けのサービスの意味</td></tr><tr><td style="text-align:left;">Webフロントエンド</td><td style="text-align:left;">ブラウザ上で動作するWebアプリケーションでユーザーが操作するUI部分のこと</td></tr><tr><td style="text-align:left;">静的ファイル</td><td style="text-align:left;">ブラウザで表示するために必要なHTML、CSS、JavaScript、画像、動画などのファイル</td></tr><tr><td style="text-align:left;">SPA</td><td style="text-align:left;">Single-page applicationの略。はウェブアプリの実装方法の一種で、単一のウェブ文書のみを読み込み、別の内容を表する際には フェッチなどの JavaScript API を通じて本文の内容を更新するもの</td></tr><tr><td style="text-align:left;">OSS</td><td style="text-align:left;">オープンソースソフトウェア</td></tr><tr><td style="text-align:left;">B/Gデプロイ</td><td style="text-align:left;">Blue/Greenデプロイメントの略。システムのダウンタイムを最小限に抑えてリリースするデプロイ手法のこと。本番環境（Blue環境）とは別に、新しいバージョン（Green環境）を構築し、ロードバランサーなどでトラフィックを切り替えることで、新旧の環境を同時に稼働させ、切り替え後の動作確認やロールバックを容易に行うことといったこと指す</td></tr><tr><td style="text-align:left;">LB</td><td style="text-align:left;">Load Balancerとは、トラフィックを複数のサーバーに分散するミドルウェアのこと</td></tr><tr><td style="text-align:left;">FaaS</td><td style="text-align:left;">Function as a Service の略。イベントに応じてコードを実行できるサーバーレスアーキテクチャのこと。AWS Lambdaが有名</td></tr></tbody></table><h2 id="本ガイドラインの構成について" tabindex="-1">本ガイドラインの構成について <a class="header-anchor" href="#本ガイドラインの構成について" aria-label="Permalink to &quot;本ガイドラインの構成について&quot;">​</a></h2><p>大まかに以下の1～8の流れで構成されている。</p><ol><li>構成方針（ホスティング、レンダリング方式、コンポーネント設計など）</li><li>要件（対応ブラウザ、サポートバージョンなど）</li><li>動作方針（バリデーション、ルーティング、状態管理など）</li><li>表示制御（レスポンシブ、画像など）</li><li>オフライン対応（PWAやオフライン判定方式など）</li><li>認証認可（認証方式、認可方針など）</li><li>開発（静的解析など）</li><li>テスト（テスト方針など）</li></ol><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 武田大輝、小杉山護、長谷川寛人、小澤泰河、中村立基、山本竜玄、宮崎将太、村田靖拓、澁川喜規、真野隼記</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.09.11 <a href="https://future-architect.github.io/articles/20250911a/" target="_blank" rel="noreferrer">Webフロントエンド設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./web_frontend_guidelines.html">Webフロントエンド設計ガイドライン</a></p></div>',23)])])}const f=e(r,[["render",n]]);export{b as __pageData,f as default};
